/**
 * The share picture, 1200 x 630, baked in as base64 so it needs no bucket.
 * Re-shoot it from /og whenever the card changes:
 *   npx playwright screenshot --viewport-size=1200,630 https://fly.diz.lt/og og.png
 */
export const OG_PNG_BASE64 =
  '';

export function ogPngBytes(): Uint8Array {
  const binary = atob(OG_PNG_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
